import scalaz._, Scalaz._

// Divisible[F]:  def divide2[A1, A2, Z](a1: F[A1], a2: F[A2])(f: Z => (A1, A2)): F[Z]; def conquer[A]: F[A]
// Decidable[F]:  def choose[Z, A1, A2](a1: => F[A1], a2: => F[A2])(f: Z => A1 \/ A2): F[Z]
val hostOk: Config => Boolean = c => c.host.nonEmpty
val portOk: Config => Boolean = c => c.port > 0 && c.port < 65536
val valid = (hostOk |@| portOk)(_ && _)          // product combination along the function applicative
